    terms=', '.join(str(prefix)+'{'+str(prefix.prefixlen)+','+str(maximum)+'}' for prefix,maximum in ranges)
    policy='filter approved_export { if source = RTS_STATIC && net ~ ['+terms+'] then { bgp_next_hop=192.0.2.254; accept; } reject; }'
