    _run('bird','-p','-c','candidate.conf')
    _run('birdc','-s','sender.ctl','configure','check','"candidate.conf"')
    before=_peer_routes()
    _run('birdc','-s','sender.ctl','configure','"candidate.conf"','timeout','4')
    committed=False
    try:
        end=time.monotonic()+1.8;observed=set()
        while time.monotonic()<end:
            observed=_peer_routes()
            if observed==expected:
                _run('birdc','-s','sender.ctl','configure','confirm')
                committed=True
                _atomic('approved.conf',candidate)
                report={'status':'committed','expected':sorted(expected),'observed':sorted(observed)}
                _atomic('apply-report.json',json.dumps(report,sort_keys=True))
                return report
            time.sleep(.04)
    finally:
        if not committed:
            _run('birdc','-s','sender.ctl','configure','undo')
            end=time.monotonic()+3
            while time.monotonic()<end:
                restored=_peer_routes()
                if restored==before:break
                time.sleep(.04)
            else:raise RuntimeError('rollback did not restore observed routes')
