for s in reserved:s.close()
seeds=''.join('route '+p+' blackhole;\n' for p in all_prefixes)
template=f"""
log stderr all; router id 192.0.2.1;
@@EXPORT_FILTER@@
protocol static seed {{ ipv4; {seeds} }}
protocol bgp peer {{
 local 127.0.0.1 port {ports[0]} as 65001; neighbor 127.0.0.1 port {ports[1]} as 65002;
 multihop; strict bind on; connect retry time 1; connect delay time 1;
 ipv4 {{ import none; next hop keep; export filter approved_export; }};
}}
"""
